const claim = $('Claim Latest Customer Turn').item.json;
const text = String(claim.combined_text || '').trim().toLowerCase();
const latest = String(claim.latest_text || text).trim().toLowerCase();
const clean = (value) => value.replace(/[!?.,]+/g, '').replace(/\s+/g, ' ').trim();
const compact = clean(text);
const latestCompact = clean(latest);
const isGreeting = (value) => /^(hi|hii+|hy|hyy+|hello|hey|salam|salaam|assalam(?:u alaikum)?|aoa)$/.test(value);
const isHelp = (value) => /^(help|how to order|what can you do|options)$/.test(value);
// If old failed messages were reclaimed, answer the newest simple message
// instead of forcing the stale backlog through Gemini. A normal rapid burst
// (within 15 seconds) is still interpreted together.
const staleBacklog = Number(claim.batch_span_seconds || 0) > 15;
const greeting = isGreeting(compact) || (staleBacklog && isGreeting(latestCompact));
const help = isHelp(compact) || (staleBacklog && isHelp(latestCompact));
let reply_text = '';
if (greeting) reply_text = 'Hi! Welcome to Pizza Bar 🍕 You can ask for the menu or deals, add items, choose delivery or pickup, place an order, or cancel an order.';
if (help) reply_text = 'You can say: “show pizza deals”, “add a large Chicken Fajita”, “delivery”, “confirm my order”, or “cancel order”. 🍕';
return $input.all().map((item) => ({ json: { ...item.json, fast_reply: greeting || help, reply_text } }));

return $input.all().map((item) => {
  const body = item.json.body || {};
  const eventId = Number(body.event_id);
  const validPayload = body.source === 'admin_dashboard'
    && body.event === 'customer_notification'
    && Number.isSafeInteger(eventId)
    && eventId > 0
    && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(body.request_id || ''));
  return { json: {
    valid_payload: validPayload,
    event_id: validPayload ? eventId : null,
    request_id: validPayload ? String(body.request_id) : null,
  } };
});

const event = $('Claim Admin Customer Event').item.json;
const raw = String($input.first().json.output || '').trim();
const orderId = String(event.order_id);
const history = JSON.stringify(event.recent_messages || []);
const preferred = String(event.preferred_language || '').toLowerCase();
const urduScript = /[\u0600-\u06ff]/.test(history);
const romanUrdu = /\b(aap|apka|aapka|mera|meri|hai|hain|nahi|shukriya|order kahan)\b/i.test(history);
const language = preferred.includes('urdu') || preferred === 'ur' || urduScript
  ? (urduScript ? 'urdu' : 'roman_urdu')
  : (romanUrdu ? 'roman_urdu' : 'english');

const english = {
  received: 'Your Order #' + orderId + ' has been received and placed successfully. 🍕',
  preparing: 'Good news! Your Order #' + orderId + ' is now being prepared. 🍕',
  oven: 'Your Order #' + orderId + ' is now in the oven. 🔥🍕',
  out_for_delivery: 'Your Order #' + orderId + ' is out for delivery. 🛵🍕',
  completed: 'Your Order #' + orderId + ' has been delivered. Enjoy! 🍕',
  cancelled: 'Your Order #' + orderId + ' has been cancelled.',
  cancellation_denied: 'Sorry, the cancellation for Order #' + orderId + ' was not approved. Your order remains active.',
};
const roman = {
  received: 'Aap ka Order #' + orderId + ' receive ho gaya hai. 🍕',
  preparing: 'Aap ka Order #' + orderId + ' ab tayyar ho raha hai. 🍕',
  oven: 'Aap ka Order #' + orderId + ' ab oven mein hai. 🔥🍕',
  out_for_delivery: 'Aap ka Order #' + orderId + ' delivery ke liye nikal gaya hai. 🛵🍕',
  completed: 'Aap ka Order #' + orderId + ' deliver ho gaya hai. Mazay se khaiye! 🍕',
  cancelled: 'Aap ka Order #' + orderId + ' cancel kar diya gaya hai.',
  cancellation_denied: 'Maazrat, Order #' + orderId + ' ki cancellation approve nahi hui. Aap ka order active hai.',
};
const urdu = {
  received: 'آپ کا آرڈر #' + orderId + ' موصول ہو گیا ہے۔ 🍕',
  preparing: 'آپ کا آرڈر #' + orderId + ' اب تیار ہو رہا ہے۔ 🍕',
  oven: 'آپ کا آرڈر #' + orderId + ' اب اوون میں ہے۔ 🔥🍕',
  out_for_delivery: 'آپ کا آرڈر #' + orderId + ' ڈیلیوری کے لیے روانہ ہو گیا ہے۔ 🛵🍕',
  completed: 'آپ کا آرڈر #' + orderId + ' ڈیلیور ہو گیا ہے۔ 🍕',
  cancelled: 'آپ کا آرڈر #' + orderId + ' منسوخ کر دیا گیا ہے۔',
  cancellation_denied: 'معذرت، آرڈر #' + orderId + ' کی منسوخی منظور نہیں ہوئی۔ آپ کا آرڈر فعال ہے۔',
};
const meaning = event.event_type === 'cancellation_denied' ? 'cancellation_denied' : event.order_status;
const fallback = (language === 'urdu' ? urdu : language === 'roman_urdu' ? roman : english)[meaning] || english[meaning];
const forbidden = {
  received: /prepar|tayyar|تیار|oven|اوون|out for delivery|delivery ke liye nikal|ڈیلیوری کے لیے روانہ|deliver(?:ed)?|deliver ho|ڈیلیور|cancel|منسوخ/i,
  preparing: /oven|اوون|out for delivery|delivery ke liye nikal|ڈیلیوری کے لیے روانہ|deliver(?:ed)?|deliver ho|ڈیلیور|cancel|منسوخ/i,
  oven: /out for delivery|delivery ke liye nikal|ڈیلیوری کے لیے روانہ|deliver(?:ed)?|deliver ho|ڈیلیور|cancel|منسوخ/i,
  out_for_delivery: /prepar|tayyar|تیار|oven|اوون|deliver(?:ed)?|deliver ho|ڈیلیور|cancel|منسوخ/i,
  completed: /prepar|tayyar|تیار|oven|اوون|out for delivery|delivery ke liye nikal|ڈیلیوری کے لیے روانہ|cancel|منسوخ/i,
  cancelled: /prepar|tayyar|تیار|oven|اوون|out for delivery|delivery ke liye nikal|ڈیلیوری کے لیے روانہ|deliver(?:ed)?|deliver ho|ڈیلیور/i,
  cancellation_denied: /has been cancelled|kar diya gaya|منسوخ کر دیا/i,
};
const requiredMeaning = {
  received: /received|receive ho|موصول/i,
  preparing: /prepar|tayyar|تیار/i,
  oven: /oven|اوون/i,
  out_for_delivery: /out for delivery|delivery ke liye nikal|ڈیلیوری کے لیے روانہ/i,
  completed: /delivered|deliver ho|ڈیلیور/i,
  cancelled: /cancelled|cancel kar|منسوخ/i,
  cancellation_denied: /not approved|approve nahi|منظور نہیں/i,
};
const mentionsOrder = raw.includes('#' + orderId) || new RegExp('\\b' + orderId + '\\b').test(raw);
const leaksInternals = /database|webhook|event[_ ]?id|prompt|admin dashboard|internal tool/i.test(raw);
const safe = raw.length > 0 && raw.length <= 700 && mentionsOrder && !leaksInternals
  && requiredMeaning[meaning]?.test(raw) && !(forbidden[meaning]?.test(raw));
return [{ json: { ...event, customer_message: safe ? raw : fallback, ai_fallback_used: !safe } }];

const item = $input.first();
const input = item?.json || {};
const customerMessage = String($('Claim Latest Customer Turn').item.json.combined_text || '');
const session = $('Upsert Customer and Session').item.json || {};
const steps = Array.isArray(input.intermediateSteps) ? input.intermediateSteps : [];
const normalizeToolName = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const cancellationStep = steps.find((step) =>
  normalizeToolName(step?.action?.tool).includes('requestcancellationapproval')
);
const draftCancellationStep = steps.find((step) =>
  normalizeToolName(step?.action?.tool) === 'cancelorder'
);

const findCancellationResult = (value, depth = 0) => {
  if (depth > 6 || value === null || value === undefined) return null;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return null;
    try {
      return findCancellationResult(JSON.parse(trimmed), depth + 1);
    } catch {
      return null;
    }
  }
  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = findCancellationResult(entry, depth + 1);
      if (found) return found;
    }
    return null;
  }
  if (typeof value !== 'object') return null;
  if (
    Object.prototype.hasOwnProperty.call(value, 'request_created')
    || Object.prototype.hasOwnProperty.call(value, 'dashboard_request_visible')
    || Object.prototype.hasOwnProperty.call(value, 'request_id')
    || Object.prototype.hasOwnProperty.call(value, 'error')
  ) return value;
  for (const key of ['output', 'data', 'rows', 'result', 'json', 'response']) {
    const found = findCancellationResult(value[key], depth + 1);
    if (found) return found;
  }
  return null;
};

const negativeIntent = /\b(?:do not|don't|dont|never)\s+(?:want\s+to\s+)?cancel\b/i.test(customerMessage)
  || /\bcancel\s+(?:mat|nahi|na)\b/i.test(customerMessage);
const cancellationMessage = !negativeIntent && Boolean(
  /\b(?:cancel|cancellation|cancelled|canceled)\b/i.test(customerMessage)
  || /(?:کینسل|منسوخ)/u.test(customerMessage)
);
const cancellationIntent = Boolean(
  cancellationStep
  || (cancellationMessage
    && !draftCancellationStep
    && (session.order_status !== 'draft' || session.active_order_id))
);
const result = findCancellationResult(cancellationStep?.observation);
const isTrue = (value) => value === true || value === 'true';
const requestCreated = isTrue(result?.request_created);
const dashboardRequestVisible = isTrue(result?.dashboard_request_visible);
const requestId = result?.request_id ?? null;
const orderId = result?.order_id ?? null;
const orderStatus = result?.order_status ?? null;
const errorCode = result?.error ? String(result.error) : null;
const submissionConfirmed = requestCreated
  && dashboardRequestVisible
  && requestId !== null
  && requestId !== ''
  && !errorCode;
const isUrdu = /[؀-ۿ]/u.test(customerMessage);
const isRomanUrdu = !isUrdu && /\b(?:mera|meri|mujhe|karna|karo|kardo|krdo|nahi|nahin|hai)\b/i.test(customerMessage);
const choose = (english, romanUrdu, urdu) => isUrdu ? urdu : (isRomanUrdu ? romanUrdu : english);
const orderLabel = orderId ? ' #' + orderId : '';
const statusLabel = orderStatus ? String(orderStatus).replace(/_/g, ' ') : '';
let output = input.output;

if (cancellationIntent) {
  if (submissionConfirmed) {
    output = choose(
      "I've sent your cancellation request for order" + orderLabel + " to the admin for review. Your order is not cancelled yet.",
      'Order' + orderLabel + ' ki cancellation request admin ko review ke liye bhej di hai. Order abhi cancel nahi hua.',
      'آرڈر' + orderLabel + ' کی منسوخی کی درخواست ایڈمن کو جائزے کے لیے بھیج دی گئی ہے۔ آرڈر ابھی منسوخ نہیں ہوا۔'
    );
  } else if (errorCode === 'multiple_cancellable_orders') {
    const options = Array.isArray(result?.order_options) ? result.order_options : [];
    const ids = options.map((option) => option?.order_id).filter(Boolean);
    const choices = ids.length ? ' Available order numbers: ' + ids.join(', ') + '.' : '';
    output = choose(
      'You have multiple active orders that can be cancelled.' + choices + ' Please tell me the order number you want to cancel.',
      'Aap ke multiple active orders cancel ho sakte hain.' + choices + ' Jis order ko cancel karna hai us ka order number batayein.',
      'آپ کے ایک سے زیادہ فعال آرڈر منسوخ ہو سکتے ہیں۔' + choices + ' براہ کرم مطلوبہ آرڈر نمبر بتائیں۔'
    );
  } else if (errorCode === 'order_not_cancellable') {
    const stage = statusLabel ? ' (' + statusLabel + ')' : '';
    output = choose(
      'Order' + orderLabel + stage + " has progressed too far to cancel under the restaurant's current policy. No cancellation request was submitted.",
      'Order' + orderLabel + stage + ' cancellation ke stage se aage nikal chuka hai. Koi cancellation request submit nahi hui.',
      'آرڈر' + orderLabel + stage + ' منسوخی کے مرحلے سے آگے بڑھ چکا ہے۔ کوئی منسوخی کی درخواست جمع نہیں ہوئی۔'
    );
  } else if (errorCode === 'no_cancellable_order') {
    output = choose(
      'There is no active order currently eligible for cancellation. No cancellation request was submitted.',
      'Abhi koi active order cancellation ke liye eligible nahi hai. Koi request submit nahi hui.',
      'اس وقت کوئی فعال آرڈر منسوخی کے قابل نہیں ہے۔ کوئی درخواست جمع نہیں ہوئی۔'
    );
  } else if (errorCode === 'requested_order_not_found') {
    output = choose(
      "I couldn't find that order for your account. Please check the order number; no cancellation request was submitted.",
      'Yeh order aap ke account mein nahi mila. Order number check karein; koi cancellation request submit nahi hui.',
      'یہ آرڈر آپ کے اکاؤنٹ میں نہیں ملا۔ براہ کرم آرڈر نمبر چیک کریں؛ کوئی منسوخی کی درخواست جمع نہیں ہوئی۔'
    );
  } else if (errorCode === 'request_already_pending' && dashboardRequestVisible && requestId) {
    output = choose(
      'A cancellation request for order' + orderLabel + " is already awaiting admin review. I haven't submitted a new request.",
      'Order' + orderLabel + ' ki cancellation request pehle se admin review mein hai. Nayi request submit nahi ki.',
      'آرڈر' + orderLabel + ' کی منسوخی کی درخواست پہلے ہی ایڈمن کے جائزے میں ہے۔ نئی درخواست جمع نہیں کی گئی۔'
    );
  } else {
    output = choose(
      "I couldn't submit your cancellation request right now. Please try again; no request has been sent to the admin.",
      'Cancellation request abhi submit nahi ho saki. Dobara try karein; admin ko koi request nahi bheji gayi.',
      'منسوخی کی درخواست ابھی جمع نہیں ہو سکی۔ دوبارہ کوشش کریں؛ ایڈمن کو کوئی درخواست نہیں بھیجی گئی۔'
    );
  }
}

return [{
  json: {
    ...input,
    output,
    cancellation_intent: cancellationIntent,
    cancellation_reply_safe: true,
    cancellation_success_claimed: cancellationIntent && submissionConfirmed,
    cancellation_submission_confirmed: cancellationIntent && submissionConfirmed,
    request_created: cancellationIntent ? requestCreated : false,
    dashboard_request_visible: cancellationIntent ? dashboardRequestVisible : false,
    request_id: cancellationIntent ? requestId : null,
    order_id: cancellationIntent ? orderId : null,
    cancellation_error: cancellationIntent ? (errorCode || (submissionConfirmed ? null : 'tool_result_missing')) : null,
  },
}];
